using System.Data;
using Microsoft.EntityFrameworkCore;
using TuTuc.Data;
using TuTuc.Models;
namespace TuTuc.Services;
public class CommunityManager(AppDbContext db)
{
 public static readonly string[] TravelStyles=["Tự túc","Phượt","Nghỉ dưỡng","Khám phá văn hóa","Thiên nhiên"];
 public static readonly string[] SharingScopes=["Public","Registered","Connected"];
 public async Task<CommunityPage> Browse(int user,CommunitySearch input)
 {
  var traveler=await IsTraveler(user);var viewer=traveler?user:0;var q=Visible(viewer);
  if(!string.IsNullOrWhiteSpace(input.Q))q=q.Where(x=>x.Destination.Contains(input.Q));if(input.From.HasValue)q=q.Where(x=>x.EndDate.Date>=input.From.Value.Date);if(input.To.HasValue)q=q.Where(x=>x.Date.Date<=input.To.Value.Date);if(input.MaxBudget.HasValue)q=q.Where(x=>x.Budget==0||x.Budget<=input.MaxBudget);if(!string.IsNullOrEmpty(input.TravelStyle))q=q.Where(x=>x.TravelStyle==input.TravelStyle);
  var total=await q.CountAsync();input.Page=Math.Max(1,input.Page);var demands=await q.OrderBy(x=>x.Date).ThenBy(x=>x.Id).Skip((input.Page-1)*20).Take(20).ToListAsync();var cards=new List<DemandCard>();foreach(var demand in demands)cards.Add(await Project(demand,viewer,traveler));return new(){Demands=cards,Search=input,Total=total,Me=user,IsTraveler=traveler};
 }
 IQueryable<Companion> Visible(int viewer)=>db.Companions.AsNoTracking().Where(x=>x.IsPublished&&x.EndDate.Date>=DateTime.Today&&db.Accounts.Any(a=>a.Id==x.OwnerId&&a.IsActive&&a.Role=="Traveler")&&(viewer==0?x.SharingScope=="Public":x.OwnerId!=viewer));
 public async Task<DemandCard?> Detail(int user,int id)
 {
  var traveler=await IsTraveler(user);var viewer=traveler?user:0;var demand=await Visible(viewer).SingleOrDefaultAsync(x=>x.Id==id);
  if(demand==null&&traveler)demand=await db.Companions.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.OwnerId==user);
  return demand==null?null:await Project(demand,viewer,traveler);
 }
 async Task<DemandCard> Project(Companion demand,int viewer,bool registered,bool forceUnconnected=false)
 {
  var owner=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==demand.OwnerId);var profile=await db.UserProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==demand.OwnerId);var connected=!forceUnconnected&&viewer>0&&await db.Connections.AnyAsync(x=>x.CompanionId==demand.Id&&x.SenderId==viewer&&x.Status=="Đã chấp nhận");
  var own=viewer==demand.OwnerId&&!forceUnconnected;var full=own||demand.SharingScope!="Connected"||connected;var showProfile=own||profile?.SharingScope=="Public"||(profile?.SharingScope=="Registered"&&registered)||(profile?.SharingScope=="Connected"&&connected);var contact=own||(connected&&demand.ShareContact&&profile?.ShareContact==true);
  var requested=viewer>0&&await db.Connections.AnyAsync(x=>x.CompanionId==demand.Id&&x.SenderId==viewer&&(x.Status=="Chờ phản hồi"||x.Status=="Đã chấp nhận"));
  return new(){Id=demand.Id,Destination=demand.Destination,Date=demand.Date,EndDate=demand.EndDate,TravelStyle=demand.TravelStyle,OwnerName=owner.Name,Description=full?demand.Description:null,Budget=full?demand.Budget:null,Wishes=full?demand.Wishes:null,People=full?demand.People:null,Bio=showProfile?owner.Bio:null,Residence=showProfile?profile?.Residence:null,Interests=showProfile?profile?.Interests:null,Email=contact?owner.Email:null,Phone=contact?owner.Phone:null,Limited=!full,Connected=connected,CanConnect=registered&&!own&&!requested&&owner.IsActive&&demand.IsPublished,SharingScope=demand.SharingScope};
 }
 public async Task<CommunityDashboard> Dashboard(int user)
 {
  var demands=await db.Companions.AsNoTracking().Where(x=>x.OwnerId==user).OrderByDescending(x=>x.Id).ToListAsync();var cs=await db.Connections.AsNoTracking().Where(x=>x.SenderId==user||db.Companions.Any(c=>c.Id==x.CompanionId&&c.OwnerId==user)).OrderByDescending(x=>x.CreatedAt).ToListAsync();var list=new List<ConnectionItem>();
  foreach(var c in cs){var d=await db.Companions.AsNoTracking().SingleAsync(x=>x.Id==c.CompanionId);var sender=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==c.SenderId);var other=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==(user==d.OwnerId?c.SenderId:d.OwnerId));var profile=await db.UserProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==other.Id);var accepted=c.Status=="Đã chấp nhận";var shareProfile=profile?.SharingScope is "Public" or "Registered"||(profile?.SharingScope=="Connected"&&accepted);var shareContact=accepted&&profile?.ShareContact==true&&(other.Id!=d.OwnerId||d.ShareContact);list.Add(new(){Connection=c,Demand=d,SenderName=sender.Name,OtherName=other.Name,OtherBio=shareProfile?other.Bio:null,OtherResidence=shareProfile?profile?.Residence:null,OtherInterests=shareProfile?profile?.Interests:null,OtherEmail=shareContact?other.Email:null,OtherPhone=shareContact?other.Phone:null,Counterpart=await Project(d,user,true),Agreements=await db.CompanionAgreements.AsNoTracking().Where(x=>x.ConnectionId==c.Id).OrderByDescending(x=>x.Revision).ToListAsync()});}
  var urls=list.Select(x=>ConnectionUrl(x.Connection.Id)).Concat(list.SelectMany(x=>x.Agreements).Select(x=>AgreementUrl(x.Id))).ToHashSet();var unread=await db.Notifications.Where(n=>n.OwnerId==user&&!n.IsRead).ToListAsync();foreach(var n in unread.Where(n=>urls.Contains(n.Url)))n.IsRead=true;if(unread.Any(n=>n.IsRead))await db.SaveChangesAsync();
  return new(){Me=user,Demands=demands,Connections=list};
 }
 public async Task<DemandInput?> Edit(int user,int id){var d=await db.Companions.AsNoTracking().SingleOrDefaultAsync(x=>x.OwnerId==user&&x.Id==id);return d==null?null:new(){Id=d.Id,Destination=d.Destination,Description=d.Description,Date=d.Date,EndDate=d.EndDate,Budget=d.Budget,People=d.People,TravelStyle=d.TravelStyle,Wishes=d.Wishes,SharingScope=d.SharingScope,ShareContact=d.ShareContact,Version=Convert.ToBase64String(d.Version)};}
 public string? ValidateDemand(DemandInput x)=>string.IsNullOrWhiteSpace(x.Destination)||x.Destination.Length>200||string.IsNullOrWhiteSpace(x.Description)||x.Description.Length>2000||x.Date.Date<DateTime.Today||x.EndDate.Date<x.Date.Date||x.Budget<0||x.Budget>1000000000||x.People<1||x.People>20||!TravelStyles.Contains(x.TravelStyle)||!SharingScopes.Contains(x.SharingScope)||(x.Wishes??"").Length>1000?"Kiểm tra điểm đến, khoảng ngày từ hôm nay, nội dung, ngân sách, số người và phạm vi chia sẻ.":null;
 public async Task<DemandPreview> Preview(int user,DemandInput input)
 {
  var account=await db.Accounts.AsNoTracking().SingleAsync(x=>x.Id==user);var d=new Companion{OwnerId=user,Name=account.Name,Destination=input.Destination,Description=input.Description,Date=input.Date,EndDate=input.EndDate,Budget=input.Budget,People=input.People,TravelStyle=input.TravelStyle,Wishes=input.Wishes??"",SharingScope=input.SharingScope,ShareContact=input.ShareContact};return new(){Draft=input,RegisteredView=await Project(d,0,true,true),PublicView=input.SharingScope=="Public"?await Project(d,0,false,true):null};
 }
 public async Task<CommunityOutcome> Save(int user,DemandInput input)
 {
  var error=ValidateDemand(input);if(error!=null)return Fail("0302-01",0,error);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);if(!await IsTraveler(user))return new(false,"Tài khoản không có quyền công bố nhu cầu.",0,403);var owner=await db.Accounts.SingleAsync(x=>x.Id==user);Companion d;
  if(input.Id==0){d=new(){OwnerId=user};db.Companions.Add(d);}else{d=(await db.Companions.SingleOrDefaultAsync(x=>x.Id==input.Id&&x.OwnerId==user))!;if(d==null)return new(false,"Không tìm thấy nhu cầu.",0,404);if(!Version(d,input.Version))return new(false,"Nhu cầu vừa thay đổi. Hãy tải lại trước khi công bố.",d.Id,409);}
  d.Name=owner.Name;d.Destination=input.Destination.Trim();d.Description=input.Description.Trim();d.Date=input.Date.Date;d.EndDate=input.EndDate.Date;d.Budget=input.Budget;d.People=input.People;d.TravelStyle=input.TravelStyle;d.Wishes=(input.Wishes??"").Trim();d.SharingScope=input.SharingScope;d.ShareContact=input.ShareContact;d.IsPublished=true;
  try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã công bố nhu cầu theo đúng phạm vi đã xem trước.",d.Id);}catch(DbUpdateConcurrencyException){return new(false,"Nhu cầu vừa thay đổi. Nội dung đang soạn được giữ lại.",input.Id,409);}
 }
 public async Task<CommunityOutcome> Stop(int user,int id,string version){var d=await db.Companions.SingleOrDefaultAsync(x=>x.Id==id&&x.OwnerId==user);if(d==null)return new(false,"Không tìm thấy nhu cầu.",0,404);if(!Version(d,version))return new(false,"Phiên bản không hợp lệ.",id,409);d.IsPublished=false;try{await db.SaveChangesAsync();return new(true,"Đã dừng công bố. Lịch sử kết nối được giữ nguyên.",id);}catch(DbUpdateConcurrencyException){return new(false,"Nhu cầu đã thay đổi. Hãy tải lại.",id,409);}}
 public async Task<CommunityOutcome> Connect(int user,int id,string? message)
 {
  if((message??"").Length>1000)return new(false,"Lời giới thiệu tối đa 1000 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);if(!await IsTraveler(user))return new(false,"Chỉ tài khoản khách đang hoạt động được kết nối.",0,403);var d=await Visible(user).SingleOrDefaultAsync(x=>x.Id==id);if(d==null)return Fail("0401-01");if(d.OwnerId==user)return Fail("0401-02");if(await db.Connections.AnyAsync(x=>x.CompanionId==id&&x.SenderId==user&&x.Status=="Chờ phản hồi"))return Fail("0401-03");if(await db.Connections.AnyAsync(x=>x.CompanionId==id&&x.SenderId==user&&x.Status=="Đã chấp nhận"))return Fail("0401-04");
  var c=new Connection{CompanionId=id,SenderId=user,Message=(message??"").Trim()};db.Connections.Add(c);try{await db.SaveChangesAsync();Notify(d.OwnerId,"DeNghiKetNoiMoi","Đề nghị kết nối mới","Có người muốn đi cùng bạn đến "+d.Destination+".",ConnectionUrl(c.Id));await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi đề nghị, chờ người nhận phản hồi.",c.Id);}catch(DbUpdateException){return Fail("0401-03");}
 }
 public async Task<CommunityOutcome> Respond(int user,int id,string version,string decision)
 {
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var c=await db.Connections.SingleOrDefaultAsync(x=>x.Id==id);if(c==null)return Fail("0401-05");var d=await db.Companions.SingleAsync(x=>x.Id==c.CompanionId);if(user!=d.OwnerId&&user!=c.SenderId)return Fail("0401-05");if(c.Status!="Chờ phản hồi")return Fail("0401-07",id);if(!Version(c,version))return Fail("0401-07",id);
  if(decision=="accept"&&user==d.OwnerId){if(!await BothActive(c,d)){c.Status="Hết hiệu lực";c.RespondedAt=DateTime.UtcNow;Notify(c.SenderId,"DeNghiHetHieuLuc","Đề nghị kết nối hết hiệu lực","Một bên đã ngừng sử dụng tài khoản.",ConnectionUrl(c.Id));await db.SaveChangesAsync();await tx.CommitAsync();return Fail("0401-08",id);}c.Status="Đã chấp nhận";Notify(c.SenderId,"DeNghiDuocChapNhan","Đề nghị kết nối được chấp nhận","Hai bạn có thể trao đổi về chuyến đi.",ConnectionUrl(c.Id));}
  else if(decision=="reject"&&user==d.OwnerId){c.Status="Từ chối";Notify(c.SenderId,"DeNghiBiTuChoi","Đề nghị kết nối bị từ chối","Người đăng nhu cầu đã từ chối đề nghị.",ConnectionUrl(c.Id));}else if(decision=="withdraw"&&user==c.SenderId){c.Status="Đã rút";Notify(d.OwnerId,"DeNghiDaRut","Đề nghị kết nối đã rút","Người gửi đã rút đề nghị.",ConnectionUrl(c.Id));}else return Fail("0401-06",id);c.RespondedAt=DateTime.UtcNow;
  try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã cập nhật đề nghị. Chấp nhận kết nối chưa phải thỏa thuận đi cùng.",id);}catch(DbUpdateConcurrencyException){return Fail("0401-07",id);}
 }
 public async Task<AgreementPage?> AgreementEditor(int user,int connectionId)=>(await OpenAgreement(user,connectionId)).Page;
 // 4.197 moTaoThoaThuan: KT1 không phải kết nối đã chấp nhận của mình → 0402-01; KT2 đã kết thúc → 0402-02; KT3 đang có đề nghị cùng ngừng → 0402-03.
 public async Task<(AgreementPage? Page,string Code)> OpenAgreement(int user,int connectionId)
 {
  var dashboard=await Dashboard(user);var item=dashboard.Connections.SingleOrDefault(x=>x.Connection.Id==connectionId&&x.Connection.Status=="Đã chấp nhận");if(item==null)return(null,"0402-01");if(Ended(item.Agreements))return(null,"0402-02");if(item.Agreements.Any(x=>x.Status=="Chờ xác nhận"&&x.Kind=="Cùng ngừng"))return(null,"0402-03");var pending=item.Agreements.FirstOrDefault(x=>x.Status=="Chờ xác nhận");var current=pending??item.Agreements.FirstOrDefault(x=>x.Status=="Đã xác nhận");var d=item.Demand;return(new(){Item=item,Draft=new(){ConnectionId=connectionId,BaseRevision=item.Agreements.Select(x=>x.Revision).DefaultIfEmpty().Max(),PendingId=pending?.Id,PendingVersion=pending==null?null:Convert.ToBase64String(pending.Version),Start=current?.Start??d.Date,End=current?.End??d.EndDate,Destination=current?.Destination??d.Destination,Budget=current?.Budget??d.Budget,CostSharing=current?.CostSharing??"",Scope=current?.Scope??"",Content=current?.Content}},"");
 }
 public async Task<CommunityOutcome> Propose(int user,AgreementInput input)
 {
  if(string.IsNullOrWhiteSpace(input.Destination)||input.Destination.Length>200||input.Start.Date<DateTime.Today||input.End.Date<input.Start.Date||input.Budget<0||input.Budget>1000000000||string.IsNullOrWhiteSpace(input.CostSharing)||input.CostSharing.Length>1000||string.IsNullOrWhiteSpace(input.Scope)||input.Scope.Length>1000||(input.Content??"").Length>2000)return Fail("0402-04");
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,input.ConnectionId);if(pair==null)return Fail("0402-01");var(c,d)=pair.Value;if(!await BothActive(c,d))return Fail("0402-05");var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).OrderByDescending(x=>x.Revision).ToListAsync();if(Ended(versions))return Fail("0402-02");if(versions.Select(x=>x.Revision).DefaultIfEmpty().Max()!=input.BaseRevision)return Fail("0402-06");var pending=versions.FirstOrDefault(x=>x.Status=="Chờ xác nhận");if(pending?.Kind=="Cùng ngừng")return Fail("0402-03");
  if(pending!=null&&(input.PendingId!=pending.Id||!SameVersion(pending.Version,input.PendingVersion)))return Fail("0402-06");var active=versions.FirstOrDefault(x=>x.Status=="Đã xác nhận");if(active!=null&&SameContent(active,input))return Fail("0402-07");
  if(pending!=null){pending.Status="Đã thay thế";pending.Reason="Đã có đề xuất nội dung mới";await db.SaveChangesAsync();}
  var a=new CompanionAgreement{ConnectionId=c.Id,Revision=input.BaseRevision+1,ProposerId=user,Start=input.Start.Date,End=input.End.Date,Destination=input.Destination.Trim(),Budget=input.Budget,CostSharing=input.CostSharing.Trim(),Scope=input.Scope.Trim(),Content=(input.Content??"").Trim()};db.CompanionAgreements.Add(a);await db.SaveChangesAsync();Notify(Other(user,c,d),"ThoaThuanChoXacNhan","Thỏa thuận đồng hành chờ xác nhận","Có phiên bản mới cần bạn xem và phản hồi.",AgreementUrl(a.Id));await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi phiên bản mới. Thỏa thuận cũ giữ hiệu lực đến khi hai bên thống nhất.",c.Id);
 }
 public async Task<CommunityOutcome> EndProposal(int user,int connectionId,int baseRevision)
 {
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,connectionId);if(pair==null)return Fail("0402-01");var(c,d)=pair.Value;if(!await BothActive(c,d))return Fail("0402-05");var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();if(Ended(versions))return Fail("0402-02");if(versions.Any(x=>x.Status=="Chờ xác nhận"))return Fail("0402-11");if(versions.Select(x=>x.Revision).DefaultIfEmpty().Max()!=baseRevision)return Fail("0402-06");var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(active==null)return Fail("0402-10");
  var stop=new CompanionAgreement{ConnectionId=c.Id,Revision=baseRevision+1,ProposerId=user,Kind="Cùng ngừng",Start=active.Start,End=active.End,Destination=active.Destination,Budget=active.Budget,CostSharing=active.CostSharing,Scope=active.Scope,Content=active.Content};db.CompanionAgreements.Add(stop);await db.SaveChangesAsync();Notify(Other(user,c,d),"DeNghiCungNgung","Đề nghị cùng ngừng đồng hành","Thỏa thuận hiện tại tiếp tục có hiệu lực trong lúc chờ phản hồi.",AgreementUrl(stop.Id));await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Đã gửi đề nghị cùng ngừng. Bạn vẫn có quyền rút riêng ngay.",c.Id);
 }
 public async Task<CommunityOutcome> Agreement(int user,int id,int revision,string version,string decision,string? reason)
 {
  if(decision is not("accept" or "reject"))return new(false,"Lựa chọn không hợp lệ.");if(decision=="reject"&&string.IsNullOrWhiteSpace(reason))return Fail("0402-09");if((reason??"").Length>500)return new(false,"Lý do tối đa 500 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var a=await db.CompanionAgreements.SingleOrDefaultAsync(x=>x.Id==id);if(a==null)return Fail("0402-01");var pair=await Pair(user,a.ConnectionId);if(pair==null)return Fail("0402-01");var(c,d)=pair.Value;if(a.ProposerId==user)return Fail("0402-08",c.Id);if(a.Status!="Chờ xác nhận"||a.Revision!=revision||!Version(a,version))return Fail("0402-06",c.Id);var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();if(Ended(versions))return Fail("0402-02",c.Id);if(!await BothActive(c,d))return Fail("0402-05",c.Id);
  a.RespondedBy=user;a.RespondedAt=DateTime.UtcNow;a.Reason=(reason??"").Trim();if(decision=="reject")a.Status="Từ chối";else{var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(a.Kind=="Cùng ngừng"){if(active==null)return Fail("0402-10",c.Id);active.Status="Đã ngừng";active.EndedBy=user;active.EndedAt=DateTime.UtcNow;a.Status="Đã ngừng";a.EndedBy=user;a.EndedAt=DateTime.UtcNow;}else{if(active!=null){active.Status="Đã thay thế";await db.SaveChangesAsync();}a.Status="Đã xác nhận";}}
  if(decision=="reject")Notify(a.ProposerId,"ThoaThuanBiTuChoi","Đề xuất đồng hành bị từ chối","Bên còn lại đã từ chối phiên bản "+a.Revision+". Thỏa thuận cũ không đổi.",AgreementUrl(a.Id));else{var type=a.Kind=="Cùng ngừng"?"ThoaThuanDaNgung":"ThoaThuanDaXacNhan";foreach(var party in new[]{a.ProposerId,user})Notify(party,type,"Thỏa thuận đồng hành: "+a.Status,"Hai bên đã xác nhận phiên bản "+a.Revision+".",AgreementUrl(a.Id));}try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,decision=="reject"?"Đã từ chối đề xuất. Thỏa thuận cũ không đổi.":"Đã ghi nhận thỏa thuận: "+a.Status+".",c.Id);}catch(DbUpdateConcurrencyException){return Fail("0402-06",c.Id);}
 }
 public async Task<CommunityOutcome> Withdraw(int user,int connectionId,string version,string? reason)
 {
  if((reason??"").Length>500)return new(false,"Lý do tối đa 500 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var pair=await Pair(user,connectionId);if(pair==null)return Fail("0402-01");var(c,d)=pair.Value;var versions=await db.CompanionAgreements.Where(x=>x.ConnectionId==c.Id).ToListAsync();var active=versions.SingleOrDefault(x=>x.Status=="Đã xác nhận");if(active==null||!Version(active,version))return Fail("0402-10",c.Id);
  active.Status="Một bên đã rút";active.EndedBy=user;active.EndedAt=DateTime.UtcNow;active.Reason=(reason??"").Trim();foreach(var pending in versions.Where(x=>x.Status=="Chờ xác nhận")){pending.Status="Đã thay thế";pending.Reason="Thỏa thuận đã kết thúc do một bên rút";}Notify(Other(user,c,d),"ThoaThuanMotBenRut","Một bên đã rút khỏi đồng hành","Thỏa thuận đã kết thúc ngay. Dịch vụ đã đặt không tự bị hủy.",AgreementUrl(active.Id));try{await db.SaveChangesAsync();await tx.CommitAsync();return new(true,"Bạn đã rút khỏi đồng hành. Thỏa thuận kết thúc ngay, không chờ bên còn lại.",c.Id);}catch(DbUpdateConcurrencyException){return Fail("0402-06",c.Id);}
 }
 async Task<(Connection,Companion)?> Pair(int user,int id){if(!await IsTraveler(user))return null;var c=await db.Connections.SingleOrDefaultAsync(x=>x.Id==id&&x.Status=="Đã chấp nhận");if(c==null)return null;var d=await db.Companions.SingleAsync(x=>x.Id==c.CompanionId);return c.SenderId==user||d.OwnerId==user?(c,d):null;}
 Task<bool> IsTraveler(int user)=>db.Accounts.AnyAsync(x=>x.Id==user&&x.Role=="Traveler"&&x.IsActive);
 async Task<bool> BothActive(Connection c,Companion d)=>await db.Accounts.CountAsync(x=>(x.Id==c.SenderId||x.Id==d.OwnerId)&&x.Role=="Traveler"&&x.IsActive)==2;
 static int Other(int user,Connection c,Companion d)=>user==d.OwnerId?c.SenderId:d.OwnerId;
 static bool Ended(IEnumerable<CompanionAgreement> versions)=>versions.Any(x=>x.Kind=="Nội dung"&&(x.Status=="Đã ngừng"||x.Status=="Một bên đã rút"));
 static bool SameContent(CompanionAgreement a,AgreementInput b)=>a.Start.Date==b.Start.Date&&a.End.Date==b.End.Date&&a.Destination==b.Destination.Trim()&&a.Budget==b.Budget&&a.CostSharing==b.CostSharing.Trim()&&a.Scope==b.Scope.Trim()&&a.Content==(b.Content??"").Trim();
 static bool SameVersion(byte[] version,string? value){try{return version.SequenceEqual(Convert.FromBase64String(value??""));}catch(FormatException){return false;}}
 bool Version<T>(T entity,string? version)where T:class{if(version==null)return false;try{var bytes=Convert.FromBase64String(version);if(bytes.Length!=8||!db.Entry(entity).Property<byte[]>("Version").CurrentValue.SequenceEqual(bytes))return false;db.Entry(entity).Property("Version").OriginalValue=bytes;return true;}catch(FormatException){return false;}}
 // Lỗi nghiệp vụ theo Bảng 4.250: thông điệp và HTTP lấy từ danh mục, kèm mã.
 static CommunityOutcome Fail(string code,int id=0,string? detail=null)=>new(false,ThongDiep.Loi(code)+(string.IsNullOrEmpty(detail)?"":" "+detail),id,ThongDiep.Http(code),code);
 // Thông báo theo Bảng 4.249: đúng loại và đường dẫn thiết kế (web chuyển hướng đường dẫn này sang trang thật).
 void Notify(int owner,string type,string title,string text,string url)=>ThongBaoLoai.Them(db,owner,type,text,url);
 public static string ConnectionUrl(int id)=>"/dong-hanh/de-nghi/xem-de-nghi/"+id;
 public static string AgreementUrl(int id)=>"/dong-hanh/thoa-thuan/xem-de-nghi/"+id;
}


